magicJs:
if (ctx.isApp) return false;

const overlay = ctx.overlay;

const layer = document.createElement('div');

layer.style.cssText = `
  position: absolute;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
`;

const style = document.createElement('style');

style.textContent = `
  @keyframes magicConfettiBehind {
    0% {
      opacity: 0;
      transform:
        translate3d(0, 0, 0)
        rotate(0deg)
        scale(.7);
    }

    8% {
      opacity: 1;
    }

    100% {
      opacity: 0;
      transform:
        translate3d(var(--x), var(--y), 0)
        rotate(var(--r))
        scale(1);
    }
  }
`;

overlay.prepend(style);
overlay.prepend(layer);

const colors = [
  '#ff6b35',
  '#ffd166',
  '#06d6a0',
  '#118ab2',
  '#ef476f',
  '#ffffff'
];

for (let i = 0; i < 110; i++) {
  const piece = document.createElement('div');

  const size = 5 + Math.random() * 7;
  const startX = 30 + Math.random() * 40;
  const startY = 45 + Math.random() * 15;

  const angle = Math.random() * Math.PI * 2;
  const distance = 180 + Math.random() * 420;

  piece.style.cssText = `
    position: absolute;
    left: ${startX}%;
    top: ${startY}%;

    width: ${size}px;
    height: ${size * .55}px;

    background: ${colors[Math.floor(Math.random() * colors.length)]};
    border-radius: 2px;

    --x: ${Math.cos(angle) * distance}px;
    --y: ${Math.sin(angle) * distance}px;
    --r: ${(Math.random() - .5) * 1600}deg;

    opacity: 0;

    animation:
      magicConfettiBehind
      ${2200 + Math.random() * 1400}ms
      cubic-bezier(.18,.65,.25,1)
      ${Math.random() * 180}ms
      forwards;
  `;

  layer.appendChild(piece);
}

setTimeout(() => {
  layer.remove();
  style.remove();
}, 4000);
